/** Multichart grid API — parent window when this doc is an iframe tile. */
function v9MultichartGridApi() {
  try {
    const shell = v9MultichartShellWindow();
    if (shell && shell.__multichartGrid) return shell.__multichartGrid;
  } catch (_) {}
  return null;
}

/** Portal target for V9 floating settings — above multichart iframes when grid is active. */
function v9SettingsPortalTarget() {
  const shell = v9MultichartShellWindow();
  const doc = shell && shell.document;
  if (!doc) {
    if (typeof document === "undefined") return null;
    return document.body;
  }
  try {
    if (shell.__multichartGrid) {
      let root = doc.getElementById("multichart-global-settings-root");
      if (!root) {
        root = doc.createElement("div");
        root.id = "multichart-global-settings-root";
        root.setAttribute("data-multichart-global-settings", "1");
        root.style.cssText = "position:fixed;inset:0;z-index:2147483646;pointer-events:none;";
        doc.body.appendChild(root);
      }
      return root;
    }
  } catch (_) {}
  return doc.body;
}

/** Multichart parent shell — floating bars must escape #chart-container overflow. */
function v9UsesFloatingUiPortal() {
  try {
    const shell = v9MultichartShellWindow();
    return !!(shell && shell.__multichartGrid);
  } catch (_) {
    return false;
  }
}

/** Portal tlBar / quick bars to the body-level root (same as shape settings). */
function v9PortalFloatingUi(node) {
  if (!node || typeof document === "undefined" || !v9UsesFloatingUiPortal()) return node;
  const target = v9SettingsPortalTarget();
  if (!target) return node;
  const portaled = React.isValidElement(node)
    ? React.cloneElement(node, {
        style: {
          ...(node.props.style || {}),
          pointerEvents: "auto",
          zIndex: Math.max(Number(node.props.style?.zIndex) || 0, 2147483645),
        },
      })
    : node;
  return createPortal(portaled, target);
}

function v9GetChartPlotMarginR() {
  try {
    const ch =
      typeof window !== "undefined" && typeof window.getActiveChart === "function"
        ? window.getActiveChart()
        : typeof window !== "undefined"
          ? window.chart
          : null;
    const m = ch && ch.margin;
    if (m && typeof m.r === "number" && m.r > 0) return m.r;
  } catch (_) {}
  return 60;
}

/** Drag clamp rect for portaled floating UI — stay inside chart plot, not over price/time axes. */
function v9FloatingUiDragBounds(zz, barW, barH, panelW = 0) {
  const shell = v9MultichartShellWindow() || (typeof window !== "undefined" ? window : null);
  const Z = zz || 1;
  const pad = 8;
  const bw = barW || 0;
  const bh = barH || 0;
  let minX = pad;
  let minY = pad;
  let maxX = ((shell && shell.innerWidth) || 1920) / Z - bw - pad;
  let maxY = ((shell && shell.innerHeight) || 1080) / Z - bh - pad;
  if (panelW > 0) {
    maxX = Math.min(maxX, shell.innerWidth / Z - bw - panelW - pad);
  }
  // Multichart: allow dragging across every tile — do not clamp to #chartWrapper (panel A only).
  try {
    if (v9MultichartGridApi()) {
      return { minX, minY, maxX, maxY };
    }
  } catch (_) {}
  try {
    const doc = shell && shell.document ? shell.document : document;
    const marginR = v9GetChartPlotMarginR();
    const marginB = 30;
    const el =
      doc.getElementById("chartWrapper") ||
      doc.querySelector(".chart-wrapper") ||
      doc.getElementById("chart-container");
    if (el) {
      const r = el.getBoundingClientRect();
      minX = Math.max(minX, r.left / Z + pad);
      minY = Math.max(minY, r.top / Z + pad);
      maxX = Math.min(maxX, (r.right - marginR) / Z - bw - pad);
      maxY = Math.min(maxY, (r.bottom - marginB) / Z - bh - pad);
      if (panelW > 0) {
        maxX = Math.min(maxX, shell.innerWidth / Z - bw - panelW - pad);
      }
    }
  } catch (_) {}
  return { minX, minY, maxX, maxY };
}

/** Chart instance that should drive the V9 pair + timeframe display. */
function v9ActiveChartInstance() {
  if (typeof window === "undefined") return null;
  // MultichartGrid: toolbar / OMS must follow the focused tile (panel B ≠ host A).
  try {
    if (typeof window.getActiveChart === "function") {
      const a = window.getActiveChart();
      if (a) return a;
    }
  } catch (_) { /* ignore */ }
  return window.chart || null;
}

/** chart.js compact ticker → V9 toolbar label (EURJPY → EUR/JPY). */
function v9NormalizeToolbarSymbol(s) {
  if (!s || typeof s !== "string") return s;
  const u = s.toUpperCase().replace(/\s+/g, "");
  if (u.includes("/")) return u;
  if (/^[A-Z]{6}$/.test(u)) return u.slice(0, 3) + "/" + u.slice(3);
  return displayChartSessionSymbol(u) || u;
}

/** Minutes east of UTC for `timeZone` at instant `dateMs` (DST-aware). */
function offsetMinutesForTimezone(timeZone, dateMs) {
  const date = new Date(dateMs);
  const formatter = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  });
  const parts = formatter.formatToParts(date);
  const map = {};
  for (const { type, value } of parts) {
    if (type !== "literal") map[type] = value;
  }
  const y = +map.year;
  const mo = +map.month - 1;
  const d = +map.day;
  const h = +map.hour;
  const mi = +map.minute;
  const s = +map.second;
  const wallAsUtc = Date.UTC(y, mo, d, h, mi, s);
  return Math.round((wallAsUtc - dateMs) / 60000);
}

/** TradingView-style `(UTC±HH:MM)` prefix (always two-digit hour and minute). */
function formatTradingViewUtcOffset(offsetMin) {
  const sign = offsetMin >= 0 ? "+" : "-";
  const abs = Math.abs(offsetMin);
  const hh = String(Math.floor(abs / 60)).padStart(2, "0");
  const mm = String(abs % 60).padStart(2, "0");
  return `(UTC${sign}${hh}:${mm})`;
}

function friendlyTzIdLabel(id) {
  return id.replace(/_/g, " ");
}

/** Sort key: UTC first, then Etc/UTC at offset 0 (TradingView-style twin UTC rows). */
function tzOffsetSortRank(id, offsetMin) {
  if (offsetMin !== 0) return 99;
  if (id === "UTC") return 0;
  if (id === "Etc/UTC") return 1;
  return 50;
}

/** Exactly 26 curated IANA zones (TradingView-style short list); rows sorted west→east by offset at runtime. */
const CHART_TIMEZONE_SELECT_IDS = Object.freeze([
  "Pacific/Midway",
  "Pacific/Honolulu",
  "America/Anchorage",
  "America/Los_Angeles",
  "America/Denver",
  "America/Chicago",
  "America/New_York",
  "America/Caracas",
  "America/Sao_Paulo",
  "Atlantic/South_Georgia",
  "Atlantic/Azores",
  "UTC",
  "Etc/UTC",
  "Europe/Paris",
  "Europe/Athens",
  "Europe/Moscow",
  "Asia/Dubai",
  "Asia/Karachi",
  "Asia/Kolkata",
  "Asia/Dhaka",
  "Asia/Bangkok",
  "Asia/Singapore",
  "Asia/Tokyo",
  "Australia/Sydney",
  "Pacific/Noumea",
  "Pacific/Auckland",
]);

/**
 * Rows for Settings → Time zone: sorted west→east by offset; label `(UTC±HH:MM) Region/City`.
 * `referenceMs` should match chart context (e.g. bar time) so DST matches the session.
 */
function getChartTimezoneSelectOptions(referenceMs) {
  const ref = Number.isFinite(referenceMs) ? referenceMs : Date.now();
  const ids = CHART_TIMEZONE_SELECT_IDS;

  const rows = [];
  for (const id of ids) {
    let offsetMin = 0;
    try {
      offsetMin = offsetMinutesForTimezone(id, ref);
    } catch (_) {
      continue;
    }
    rows.push({
      id,
      offsetMin,
      label: `${formatTradingViewUtcOffset(offsetMin)} ${friendlyTzIdLabel(id)}`,
    });
  }

  rows.sort((a, b) => {
    if (a.offsetMin !== b.offsetMin) return a.offsetMin - b.offsetMin;
    const ra = tzOffsetSortRank(a.id, a.offsetMin);
    const rb = tzOffsetSortRank(b.id, b.offsetMin);
    if (ra !== rb) return ra - rb;
    return a.id.localeCompare(b.id);
  });

  return rows;
}

function formatChartTimezoneSettingDisplay(ianaId, referenceMs) {
  const id = resolveV9TimezoneToId(ianaId);
  const ref = Number.isFinite(referenceMs) ? referenceMs : Date.now();
  let off = 0;
  try {
    off = offsetMinutesForTimezone(id, ref);
  } catch (_) {}
  return `${formatTradingViewUtcOffset(off)} ${friendlyTzIdLabel(id)}`;
}

/** Bar / replay time (ms) for V9 bottom HUD — matches trade-row “now” semantics. */
function getV9ChartBarTimeMs(chart) {
  if (!chart) return Date.now();
  try {
    const rs = chart.replaySystem;
    // Prefer active replay playhead (INTERVAL-stepped virtual time).
    if (rs && rs.isActive && Number.isFinite(rs.replayTimestamp)) {
      return rs.replayTimestamp;
    }
  } catch (_) {}
  try {
    const data = Array.isArray(chart.data) && chart.data.length ? chart.data : chart.rawData;
    if (Array.isArray(data) && data.length) {
      const last = data[data.length - 1];
      if (last && Number.isFinite(last.t)) return last.t;
    }
  } catch (_) {}
  return Date.now();
}

function formatV9HudDateLine(ms) {
  const tm = typeof window !== "undefined" ? window.timezoneManager : null;
  const convert =
    tm && typeof tm.convertToTimezone === "function" ? (t) => tm.convertToTimezone(t) : null;
  return formatV9HudDateLineTitle(ms, convert);
}

function formatV9HudClock(ms, use12h) {
  if (!Number.isFinite(ms)) return "—";
  const tm = typeof window !== "undefined" ? window.timezoneManager : null;
  const d =
    tm && typeof tm.convertToTimezone === "function" ? tm.convertToTimezone(ms) : new Date(ms);
  const hh = d.getUTCHours();
  const mm = d.getUTCMinutes();
  const ss = d.getUTCSeconds();
  const pad = (n) => String(n).padStart(2, "0");
  const raw = `${pad(hh)}:${pad(mm)}:${pad(ss)}`;
  if (!use12h) return raw;
  const h12 = hh % 12 || 12;
  const ampm = hh >= 12 ? "PM" : "AM";
  return `${String(h12).padStart(2, "0")}:${pad(mm)} ${ampm}`;
}

/** Futures + lot-size TP rows: integer contracts per leg summing to orderQtyFloor → OM percentages. */
function v9TpNormalizeFuturesContractShares(rawQtyStrings, orderQtyFloor) {
  const n = rawQtyStrings.length;
  if (!n || orderQtyFloor < 1) return rawQtyStrings.map(() => 0);
  const ri = rawQtyStrings.map((q) => Math.max(0, Math.round(parseFloat(q) || 0)));
  let sum = ri.reduce((a, b) => a + b, 0);
  if (sum === 0) {
    const per = Math.floor(orderQtyFloor / n);
    const extra = orderQtyFloor - per * n;
    return ri.map((_, i) => per + (i < extra ? 1 : 0));
  }
  if (sum === orderQtyFloor) return ri;
  const scaled = ri.map((c) => (sum > 0 ? (c * orderQtyFloor) / sum : 0));
  const floors = scaled.map((x) => Math.floor(x));
  let used = floors.reduce((a, b) => a + b, 0);
  let rem = orderQtyFloor - used;
  const order = scaled
    .map((x, i) => ({ i, frac: x - floors[i] }))
    .sort((a, b) => b.frac - a.frac || a.i - b.i);
  const out = [...floors];
  for (let k = 0; k < rem && k < order.length; k++) out[order[k].i]++;
  return out;
}

/** Forex lot-size TP rows: decimal lots per leg summing exactly to orderQty (centilots + largest remainder). */
function v9TpNormalizeDecimalLotShares(rawQtyStrings, orderQty, decimals = 2) {
  const n = rawQtyStrings.length;
  const scale = Math.pow(10, Math.max(0, decimals));
  const totalUnits = Math.round(Math.max(0, Number(orderQty) || 0) * scale);
  if (!n || totalUnits <= 0) return rawQtyStrings.map(() => (0).toFixed(decimals));

  const units = rawQtyStrings.map((q) => Math.max(0, Math.round((parseFloat(q) || 0) * scale)));
  let sum = units.reduce((a, b) => a + b, 0);

  if (sum === 0) {
    const per = Math.floor(totalUnits / n);
    const extra = totalUnits - per * n;
    return units.map((_, i) => ((per + (i < extra ? 1 : 0)) / scale).toFixed(decimals));
  }

  if (sum === totalUnits) {
    return units.map((u) => (u / scale).toFixed(decimals));
  }

  const scaled = units.map((c) => (sum > 0 ? (c * totalUnits) / sum : 0));
  const floors = scaled.map((x) => Math.floor(x));
  let used = floors.reduce((a, b) => a + b, 0);
  let rem = totalUnits - used;
  const order = scaled
    .map((x, i) => ({ i, frac: x - floors[i] }))
    .sort((a, b) => b.frac - a.frac || a.i - b.i);
  const out = [...floors];
  for (let k = 0; k < rem && k < order.length; k++) out[order[k].i]++;
  return out.map((u) => (u / scale).toFixed(decimals));
}

/** Lot-size (#) panel: total contracts/lots available for TP legs. */
function v9TpOrderLotTotal(riskVal, omOrderQtyTxt, sizeMode, symbolType) {
  if (sizeMode !== "#") return 0;
  const qRv = Math.max(0, parseFloat(riskVal || "0"));
  const qOm = Math.max(0, parseFloat(omOrderQtyTxt || "0"));
  const qCore = qRv >= 1 ? qRv : qOm > 0 ? qOm : qRv;
  return symbolType === "futures" ? Math.floor(qCore) : qCore;
}

/** Lot-size (#) / $ / %: total size for Entry (+) affordances — multi-entry uses row sum. */
function v9EntryOrderLotTotal(riskVal, omOrderQtyTxt, sizeMode, symbolType, entryRows) {
  if (sizeMode === "#" && Array.isArray(entryRows) && entryRows.length > 1) {
    const sum = entryRows.reduce((s, r) => s + (parseFloat(r.risk) || 0), 0);
    if (sum > 0) return symbolType === "futures" ? Math.floor(sum) : sum;
  }
  if (sizeMode === "#") return v9TpOrderLotTotal(riskVal, omOrderQtyTxt, sizeMode, symbolType);
  const qOm = Math.max(0, parseFloat(omOrderQtyTxt || "0"));
  if (qOm > 0) return qOm;
  return Math.max(0, parseFloat(riskVal || "0"));
}

/** Single TP (#): clamp leg qty to [0, orderTotal]. */
function v9TpClampSingleLotQty(rawVal, orderTotal, symbolType) {
  if (rawVal === "" || rawVal === ".") return rawVal;
  const n = parseFloat(rawVal);
  if (!Number.isFinite(n)) return symbolType === "futures" ? "0" : "0";
  const max = Math.max(0, orderTotal);
  let clamped = Math.max(0, n);
  if (symbolType === "futures") clamped = Math.round(clamped);
  if (clamped > max) clamped = max;
  return symbolType === "futures" ? String(Math.round(clamped)) : String(clamped);
}

/** Multi TP (#): scale leg lots so the sum equals orderTotal. */
function v9TpNormalizeMultiLotRows(rows, orderTotal, symbolType) {
  const active = rows.filter((r) => r.enabled !== false);
  if (active.length < 2 || !(orderTotal > 0)) return rows;
  const shares =
    symbolType === "futures"
      ? v9TpNormalizeFuturesContractShares(
          active.map((r) => r.qty),
          Math.floor(orderTotal)
        )
      : v9TpNormalizeDecimalLotShares(active.map((r) => r.qty), orderTotal, 2);
  let changed = false;
  const next = rows.map((row) => {
    if (row.enabled === false) return row;
    const ix = active.findIndex((a) => a.id === row.id);
    if (ix < 0) return row;
    const w = symbolType === "futures" ? String(shares[ix] ?? 0) : shares[ix] ?? "0.00";
    if (String(row.qty) !== w) changed = true;
    return { ...row, qty: w };
  });
  return changed ? next : rows;
}

/** OM TP percentages + total contracts → integer shares (largest remainder). */
function v9TpFuturesContractsFromPercentages(percentages, orderQtyFloor) {
  const n = percentages.length;
  if (!n || orderQtyFloor < 1) return percentages.map(() => 0);
  const raw = percentages.map((pct) => ((parseFloat(pct) || 0) / 100) * orderQtyFloor);
  const floors = raw.map((x) => Math.floor(x));
  let used = floors.reduce((a, b) => a + b, 0);
  let rem = orderQtyFloor - used;
  const order = raw
    .map((x, i) => ({ i, frac: x - floors[i] }))
    .sort((a, b) => b.frac - a.frac || a.i - b.i);
  const out = [...floors];
  for (let k = 0; k < rem && k < order.length; k++) out[order[k].i]++;
  return out;
}

/** $-mode multi-TP: total $ at risk — SIZE (`riskVal`) or sum of entry legs when split. */
function v9TpDollarBasisForSplit(entryRows, riskVal) {
  const rv = Math.max(0, parseFloat(String(riskVal ?? "0")) || 0);
  if (!Array.isArray(entryRows) || entryRows.length <= 1) return rv;
  const es = entryRows.reduce((s, r) => s + (parseFloat(String(r?.risk ?? "0")) || 0), 0);
  return es > 0 ? es : rv;
}

function v9SizeModeToTpDistribution(sizeMode) {
  if (sizeMode === "$") return "amount";
  if (sizeMode === "#") return "lots";
  return "percent";
}

/** om.tpTargets[idx] → React row.qty for the active panel size mode (matches chart slice lots). */
function v9OmTpTargetToReactQty(om, targetIndex, sizeMode, symbolType) {
  if (!om?.tpTargets?.[targetIndex]) return "0";
  const t = om.tpTargets[targetIndex];
  const distMode = t.distributionMode || om.tpDistributionMode || v9SizeModeToTpDistribution(sizeMode);
  const entryPx =
    typeof om._getReferenceEntryForOrderMath === "function"
      ? om._getReferenceEntryForOrderMath()
      : parseFloat(document.getElementById("orderEntryPrice")?.value || 0);
  const oq = parseFloat(document.getElementById("orderQuantity")?.value || 0);
  const side =
    om.orderSide ||
    (document.getElementById("buyTab")?.classList.contains("active") ? "BUY" : "SELL");

  if (sizeMode === "#" && symbolType === "futures") {
    const oqFloor = Math.floor(Math.max(0, oq));
    const shares = v9TpFuturesContractsFromPercentages(
      om.tpTargets.map((x) => x.percentage),
      oqFloor
    );
    return String(shares[targetIndex] ?? 0);
  }

  if (sizeMode === "#") {
    const eff =
      typeof om._computeEffectiveTPPercentages === "function"
        ? om._computeEffectiveTPPercentages(entryPx, oq, side, {
            tpTargets: om.tpTargets,
            distributionMode: distMode,
          })
        : [];
    const lots = oq * ((eff[targetIndex] || 0) / 100);
    if (!(lots > 0)) return "0";
    if (symbolType === "futures") return String(Math.round(lots));
    const allocated =
      typeof om._allocateTpLotsByLargestRemainder === "function" && distMode === "lots"
        ? om._allocateTpLotsByLargestRemainder(
            oq,
            om.tpTargets.map((x) => (x?.price > 0 ? x.percentage || 0 : 0))
          )
        : null;
    if (allocated && allocated[targetIndex] != null) {
      return Number(allocated[targetIndex]).toFixed(2);
    }
    return lots.toFixed(2);
  }

  if (sizeMode === "$" && distMode === "amount") {
    return String(t.percentage ?? 0);
  }

  if (sizeMode === "%" && distMode === "percent") {
    return String(t.percentage ?? 0);
  }

  const eff =
    typeof om._computeEffectiveTPPercentages === "function"
      ? om._computeEffectiveTPPercentages(entryPx, oq, side, {
          tpTargets: om.tpTargets,
          distributionMode: distMode,
        })
      : [];
  const ePct = eff[targetIndex] || 0;
  if (sizeMode === "%") {
    return ePct > 0 ? String(parseFloat(ePct.toFixed(1))) : "0";
  }
  return String(t.percentage ?? 0);
}

/** Share lots for one TP rung — same math as chart labels. */
function v9OmTpShareLotsAt(om, targetIndex, symbolType) {
  const oq = parseFloat(document.getElementById("orderQuantity")?.value || 0);
  const fmtOq = () =>
    symbolType === "futures"
      ? String(Math.max(0, Math.round(oq)))
      : (Number.isFinite(oq) ? oq.toFixed(2) : "0.00");
  // Single-TP mode often leaves om.tpTargets empty — still show full order size, not "0 Contracts".
  if (!om?.tpTargets?.[targetIndex]) {
    return oq > 0 ? fmtOq() : symbolType === "futures" ? "0" : "0.00";
  }
  const entryPx =
    typeof om._getReferenceEntryForOrderMath === "function"
      ? om._getReferenceEntryForOrderMath()
      : parseFloat(document.getElementById("orderEntryPrice")?.value || 0);
  const side = om.orderSide || "BUY";
  const eff =
    typeof om._computeEffectiveTPPercentages === "function"
      ? om._computeEffectiveTPPercentages(entryPx, oq, side, { tpTargets: om.tpTargets })
      : [];
  const lots = oq * ((eff[targetIndex] || 0) / 100);
  if (!(lots > 0)) {
    // Ladder present but effective % not ready yet — fall back to full order qty for the sole rung.
    if (om.tpTargets.length === 1 && oq > 0) return fmtOq();
    return symbolType === "futures" ? "0" : "0.00";
  }
  return symbolType === "futures" ? String(Math.round(lots)) : lots.toFixed(2);
}

function formatV9AccountNum(n, { fractionDigits = null } = {}) {
  const x = Number(n);
  if (!Number.isFinite(x)) return "—";
  const min = fractionDigits == null ? 0 : fractionDigits;
  const max = fractionDigits == null ? 2 : fractionDigits;
  return x.toLocaleString(undefined, { minimumFractionDigits: min, maximumFractionDigits: max });
}

const V9_BALANCE_VISIBLE_KEY = "v9BalanceVisible";

function readV9BalanceVisible() {
  try {
    const v = typeof window !== "undefined" ? localStorage.getItem(V9_BALANCE_VISIBLE_KEY) : null;
    return v === null ? true : v === "1";
  } catch {
    return true;
  }
}

function maskV9AccountValue(visible, text) {
  return visible ? text : "••••••";
}

function formatV9HudSessionPnl(om) {
  if (!om) return { text: "—", nonNeg: true };
  const fmtSigned = (x) => {
    const abs = Math.abs(x).toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
    return `${x >= 0 ? "+" : "-"}${abs}`;
  };
  const init = Number(om.initialBalance);
  const eq = Number(om.equity);
  if (Number.isFinite(init) && Number.isFinite(eq)) {
    const x = eq - init;
    return { text: fmtSigned(x), nonNeg: x >= 0 };
  }
  const r = Number(om.realizedPnL);
  if (Number.isFinite(r)) return { text: fmtSigned(r), nonNeg: r >= 0 };
  return { text: "—", nonNeg: true };
}

function v9HudTzShortLabel(fallbackSettingsTz) {
  const tm = typeof window !== "undefined" ? window.timezoneManager : null;
  if (tm && typeof tm.getShortLabel === "function") return tm.getShortLabel();
  return String(fallbackSettingsTz || "UTC").split(" ")[0];
}

/** V9 drawing panel uses `tlStyle.showInfo` + `showInfoTypes` (labels); chart.js reads `drawing.style.infoSettings` booleans. */
const V9_INFO_LABEL_TO_PROP = {
  "Price range": "priceRange",
  "Percent change": "percentChange",
  "Change in pips": "changeInPips",
  "Bars range": "barsRange",
  "Date/time range": "dateTimeRange",
  "Volume": "volume",
  "Distance": "distance",
  "Angle": "angle",
};
const V9_INFO_PROP_TO_LABEL = Object.fromEntries(
  Object.entries(V9_INFO_LABEL_TO_PROP).map(([label, prop]) => [prop, label])
);

/** Sub-tool icon ids per left-rail group (matches `toolGroups` dd). Used to clamp stale `groupSelected` so the Shapes rail cannot show a Lines icon.
 * Arrow tools (`arrowMarker` … `arrowDn`) belong to group `rect` only (Shapes dropdown); chart arrow drawings map there so the Lines rail is not overwritten. */
/** Left-rail drawing tool groups — clicking the same group again must not deselect the chart shape. */
const V9_DRAWING_TOOL_GROUP_IDS = new Set([
  "trendline", "rect", "channel", "brush2", "fib", "pattern", "measure", "text", "brush",
]);

function v9IsPersistentFreehandArmed(dm) {
  const t = dm && dm.currentTool;
  return t === "brush" || t === "highlighter";
}

function v9IsFreehandLegacyTool(legacyTool) {
  const t = String(legacyTool || "").toLowerCase();
  return t === "brush" || t === "highlighter";
}

const V9_FREEHAND_ICON_TO_LEGACY = { draw: "brush", brush: "highlighter" };

function v9ShouldClearChartSelectionForRailClick(nextToolId, currentTool) {
  if (!V9_DRAWING_TOOL_GROUP_IDS.has(nextToolId)) return false;
  return nextToolId !== currentTool;
}

/** Ctrl+marquee multi-select keeps shapes selected without tlBarSelected — still clear before arming a tool. */
function v9ClearChartSelectionBeforeRailTool(chartInstance, nextToolId, currentTool, tlBarSelected) {
  if (!V9_DRAWING_TOOL_GROUP_IDS.has(nextToolId)) return;
  const dmSel = chartInstance && chartInstance.drawingManager;
  const hasSelected = !!(dmSel && Array.isArray(dmSel.selectedDrawings) && dmSel.selectedDrawings.length > 0);
  if (!hasSelected && !(tlBarSelected && v9ShouldClearChartSelectionForRailClick(nextToolId, currentTool))) {
    return;
  }
  try {
    if (dmSel && typeof dmSel.deselectAll === "function") {
      dmSel.deselectAll({ forSelectionChange: true });
    }
    if (dmSel && dmSel.toolbar && typeof dmSel.toolbar.hide === "function") {
      dmSel.toolbar.hide();
    }
  } catch (_) {}
}

