/** V9 group id → default legacy tool when no sub-tool is picked yet. */
const V9_GROUP_DEFAULT = Object.freeze({
  crosshair: null, brush2: 'brush', trendline: 'trendline', rect: 'rectangle',
  channel: 'parallel-channel', fib: 'fibonacci-retracement', text: 'text',
  pattern: 'elliott-impulse', measure: 'date-price-range', brush: 'anchored-vwap',
  eye: null, magnet: null, lock: null,
});

/** Resolve legacy chart.js tool id from rail group + sub-tool (no React hook). */
function v9ResolveLegacyToolFromRailState(toolId, groupSelected) {
  const sub = groupSelected && groupSelected[toolId];
  if (sub && sub.icon && V9_ICON_TO_LEGACY[sub.icon] !== undefined) {
    return V9_ICON_TO_LEGACY[sub.icon];
  }
  if (V9_GROUP_DEFAULT[toolId] !== undefined) return V9_GROUP_DEFAULT[toolId];
  if (V9_ICON_TO_LEGACY[toolId] !== undefined) return V9_ICON_TO_LEGACY[toolId];
  return null;
}

/** Multichart host tile (panel A): arm drawingManager synchronously on sidebar click. */
function v9TryArmHostDrawingToolImmediate(toolId, groupSelected) {
  try {
    const grid = typeof window !== "undefined" ? window.__multichartGrid : null;
    if (!grid || grid.hostPanelId == null) return;
    const fid = typeof grid.getFocusedPanelId === "function" ? grid.getFocusedPanelId() : null;
    if (fid !== grid.hostPanelId) return;
    const legacy = v9ResolveLegacyToolFromRailState(toolId, groupSelected);
    if (!legacy) return;
    const dm = window.chart && window.chart.drawingManager;
    if (!dm || typeof dm.setTool !== "function") return;
    if (dm.currentTool !== legacy) dm.setTool(legacy);
  } catch (_) {}
}

/** V9 fib rail icons that expose an Input tab (matches legacy `isFibonacciInputTabTool`). */
const V9_FIB_ICONS_WITH_INPUT_TAB = new Set([
  "fib", "fibExtension", "fibChannel", "fibTimeZone", "fibFan", "fibTime",
  "fibCircles", "fibArcs", "fibWedge",
]);

/** Rail icons with no settings Text tab (and no working quick-menu text color). Shared by settings tabs + floating bar. */
const V9_ICONS_WITHOUT_TEXT_TAB = (() => {
  const s = new Set([
    ...V9_RAIL_ICONS_BY_GROUP.fib,
    ...V9_RAIL_ICONS_BY_GROUP.pattern,
    ...V9_RAIL_ICONS_BY_GROUP.measure,
    ...V9_RAIL_ICONS_BY_GROUP.brush2,
    "crossLine", "polyline", "pathTool", "curve", "doubleCurve",
    "triangle", "arcShape", "ellipse", "circle",
    "channel", "regressionCh", "flatChannel", "disjointCh", "pitchfork",
    "priceNote",
  ]);
  return s;
})();

function v9ToolHasTextTab(icon) {
  if (!icon || typeof icon !== "string") return false;
  return !V9_ICONS_WITHOUT_TEXT_TAB.has(icon);
}

/** Hide floating-toolbar line STYLE + THICKNESS when the settings panel already exposes them. */
function v9HideFloatingBarLineStyleAndWidth(icon) {
  if (!icon || typeof icon !== "string") return false;
  if (icon.startsWith("fib")) return true;
  if (icon === "gannBox" || icon === "gannSquare" || icon === "gannFan") return true;
  if (icon === "regressionCh" || icon === "measure" || icon === "channel") return true;
  return false;
}

function v9TlQuickBarIcon(chartPrimarySelectedDrawingType, panelGroup, subToolIcon) {
  return (
    (chartPrimarySelectedDrawingType &&
      v9SubToolIconFromDrawingType(chartPrimarySelectedDrawingType, panelGroup)) ||
    subToolIcon
  );
}

/** Pitchfork median uses `bold` (solid) instead of generic `solid` line type. */
function v9PitchforkMedianTypeFromQuickBarLineType(lineType) {
  return lineType === "solid" ? "bold" : lineType;
}

function v9QuickBarLineTypeFromPitchforkMedian(pfMedianType) {
  return pfMedianType === "bold" ? "solid" : pfMedianType || "dashed";
}

/** Hide floating-toolbar text color (A) when the tool has no Text tab. */
function v9HideFloatingBarTextColor(icon) {
  return !v9ToolHasTextTab(icon);
}

/** Text/annotation settings + content tab (not emoji/image/flag/price-note). */
function v9TxtIconHasContentTab(icon) {
  if (!icon || typeof icon !== "string") return false;
  return !["emoji", "image", "flag", "priceNote"].includes(icon);
}

/** Quick-bar text field — prefer React state, fall back to live drawing.text. */
function v9IsTextToolPlaceholderText(text) {
  try {
    const helpers = typeof window !== "undefined" ? window.DrawingTextHelpers : null;
    if (helpers && typeof helpers.isTextToolPlaceholder === "function") {
      return helpers.isTextToolPlaceholder(text);
    }
  } catch (_) {}
  const t = String(text == null ? "" : text).trim();
  if (!t) return true;
  if (/^add text$/i.test(t)) return true;
  if (/^type here$/i.test(t)) return true;
  if (/^enter text/i.test(t)) return true;
  if (/^(text|note|notebox|callout|comment|pin|label|anchored text|price note|signpost|signpost-2)$/i.test(t)) return true;
  return false;
}

function v9NormalizeTxtPanelContent(text) {
  const raw = text == null ? "" : String(text);
  return v9IsTextToolPlaceholderText(raw) ? "" : raw;
}

function v9ResolveTxtQuickBarContent(txtStyleContent, liveDrawing) {
  const fromState = v9NormalizeTxtPanelContent(txtStyleContent);
  if (fromState.trim() !== "") return fromState;
  if (liveDrawing && typeof liveDrawing.text === "string") {
    return v9NormalizeTxtPanelContent(liveDrawing.text);
  }
  return fromState;
}

function v9RailSubtoolOrFallback(groupId, sel, fallback) {
  const allowed = V9_RAIL_ICONS_BY_GROUP[groupId];
  if (!allowed) return sel || fallback;
  if (sel && sel.icon && allowed.has(sel.icon)) return sel;
  return fallback;
}

