const V9_KNOWN_SYMBOL_CATALOG = SYMBOLS_DATA.flatMap((c) =>
  c.items.map((it) => ({ ...it, cat: c.cat }))
);

function v9NormSymKey(x) {
  return String(x || "").toUpperCase().replace(/\s+/g, "").replace(/\//g, "");
}

const V9_FX_FRIENDLY = {
  EUR: "Euro", USD: "Dollar", GBP: "Pound", JPY: "Yen",
  AUD: "Aussie", CAD: "Canadian", NZD: "Kiwi", CHF: "Franc",
};

function v9FxFriendlyName(base, quote) {
  const b = V9_FX_FRIENDLY[base];
  const q = V9_FX_FRIENDLY[quote];
  return (b && q) ? `${b} / ${q}` : `${base} / ${quote}`;
}

function v9ParseFxPairForDropdown(raw) {
  const u = String(raw || "").toUpperCase().replace(/\s+/g, "");
  if (u.includes("/")) {
    const p = u.split("/").filter(Boolean);
    if (p.length === 2 && p[0].length === 3 && p[1].length === 3) {
      return {
        id: `${p[0]}/${p[1]}`,
        name: v9FxFriendlyName(p[0], p[1]),
        type: "forex",
        base: p[0],
        quote: p[1],
      };
    }
  }
  if (/^[A-Z]{6}$/.test(u)) {
    const base = u.slice(0, 3);
    const quote = u.slice(3);
    return {
      id: `${base}/${quote}`,
      name: v9FxFriendlyName(base, quote),
      type: "forex",
      base,
      quote,
    };
  }
  return null;
}

/** Map session / inferred asset class → dropdown section (matches session-creation markets). */
function v9SessionCatFromAsset(assetClass, ticker) {
  const hinted = normalizeBadgeAsset(assetClass);
  const inferred = hinted || inferChartAssetClass(ticker);
  if (inferred === "Forex") return "FOREX";
  if (inferred === "Futures") return "FUTURES";
  if (inferred === "Crypto") return "CRYPTO";
  if (inferred === "Stocks") return "STOCKS";
  return "BACKTEST";
}

function v9TypeFromCat(cat) {
  if (cat === "FOREX") return "forex";
  if (cat === "FUTURES") return "futures";
  if (cat === "CRYPTO") return "crypto";
  if (cat === "STOCKS") return "stock";
  return "other";
}

function v9BuildSessionSymbolEntry(ticker, fileId, assetClass, known = V9_KNOWN_SYMBOL_CATALOG, supporting = false) {
  const rawLabel = String(ticker || "").trim();
  const extracted = extractDatasetTicker(rawLabel) || rawLabel;
  const cleanedTicker = displayChartSessionSymbol(extracted) || extracted;
  const cat = v9SessionCatFromAsset(assetClass, cleanedTicker);
  const badgeAsset =
    normalizeBadgeAsset(assetClass) ||
    (cat === "FOREX"
      ? "Forex"
      : cat === "FUTURES"
        ? "Futures"
        : cat === "CRYPTO"
          ? "Crypto"
          : cat === "STOCKS"
            ? "Stocks"
            : undefined);
  const withMeta = (row) => ({
    ...row,
    cat,
    type: row.type || v9TypeFromCat(cat),
    fileId,
    // Supporting symbols are view-only context rather than tradable pairs. The
    // dropdown had no way to tell the two apart, so they rendered identically.
    supporting: !!supporting,
    ...(badgeAsset ? { badgeAsset } : {}),
  });

  // Catalog is only for icon colors / friendly labels — never for section grouping.
  let found = known.find((s) => s.id === cleanedTicker);
  if (!found && cleanedTicker) {
    found = known.find((s) => v9NormSymKey(s.id) === v9NormSymKey(cleanedTicker));
  }
  if (found) {
    const displayId =
      found.type === "forex" ? found.id : displayChartSessionSymbol(found.id) || found.id;
    // Keep catalog friendly subtitle (e.g. "Euro / Yen"); primary line uses id/ticker.
    const friendly =
      found.name && v9NormSymKey(found.name) !== v9NormSymKey(displayId) ? found.name : null;
    return withMeta({
      ...found,
      id: displayId,
      name: friendly || displayId,
    });
  }

  const fx = v9ParseFxPairForDropdown(cleanedTicker);
  if (fx) {
    return withMeta({
      ...fx,
      name: fx.name || fx.id,
    });
  }

  const parts = (cleanedTicker || "").split("/");
  if (parts.length === 2 && parts[0].length === 3 && parts[1].length === 3) {
    const b = parts[0].toUpperCase();
    const q = parts[1].toUpperCase();
    return withMeta({
      id: `${b}/${q}`,
      name: v9FxFriendlyName(b, q),
      type: "forex",
      base: b,
      quote: q,
    });
  }

  return withMeta({
    id: cleanedTicker,
    name: cleanedTicker,
    type: v9TypeFromCat(cat),
  });
}

/**
 * Supporting symbols read gold wherever they appear. Same value the session
 * creation picker already uses for the supporting column, so a pair keeps one
 * colour from the moment it is chosen to the moment it is listed.
 */
const V9_SUPPORTING_GOLD = "var(--support)";

const V9_SESSION_CAT_ORDER = ["FOREX", "FUTURES", "CRYPTO", "STOCKS", "BACKTEST"];

/** Session pair list for symbol dropdowns — same source as header MARKETS picker. */
function v9BuildSessionSymbolGroups(sessionPairs, fallbackSymbol) {
  const items =
    sessionPairs?.length > 0
      ? sessionPairs.map((p) =>
          v9BuildSessionSymbolEntry(p.ticker, p.fileId, p.assetClass, V9_KNOWN_SYMBOL_CATALOG, p.supporting))
      : [v9BuildSessionSymbolEntry(fallbackSymbol, null, null)];
  const byCat = {};
  items.forEach((it) => {
    const k = it.cat || "BACKTEST";
    (byCat[k] ||= []).push(it);
  });
  return Object.entries(byCat)
    .sort(([a], [b]) => {
      const ia = V9_SESSION_CAT_ORDER.indexOf(a);
      const ib = V9_SESSION_CAT_ORDER.indexOf(b);
      return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
    })
    .map(([cat, catItems]) => ({ cat, items: catItems }));
}

/** Opt-in only: pad thin sessions with catalog forex. Auto-DEV padding was
 *  inventing Trading/Supporting rows that looked like role swaps on select. */
function v9SymPreviewEnabled(_sessionPairs) {
  if (typeof window === "undefined") return false;
  try {
    if (window.__V9_SYM_PREVIEW === true) return true;
    if (window.__V9_SYM_PREVIEW === false) return false;
    const q = new URLSearchParams(window.location.search || "");
    if (q.get("v9SymPreview") === "1") return true;
    if (q.get("v9SymPreview") === "0") return false;
    if (localStorage.getItem("v9_sym_preview") === "1") return true;
    if (localStorage.getItem("v9_sym_preview") === "0") return false;
  } catch (_) { /* ignore */ }
  return false;
}

/**
 * Header symbol menu: Trading vs Supporting from the loaded session.
 * In live/dev (or ?v9SymPreview=1), thin sessions get a visual multi-symbol preview.
 * Compare (+) overlays on the chart (no picker); up to 4 on top of the primary.
 * FileIds resolve from the session row, or from chart.compareOverlay.availableFiles.
 */
function v9BuildRoleSymbolGroups(sessionPairs, fallbackSymbol) {
  const sessionItems =
    sessionPairs?.length > 0
      ? sessionPairs.map((p) =>
          v9BuildSessionSymbolEntry(p.ticker, p.fileId, p.assetClass, V9_KNOWN_SYMBOL_CATALOG, p.supporting))
      : [v9BuildSessionSymbolEntry(fallbackSymbol, null, null)];
  let trading = sessionItems.filter((s) => !s.supporting);
  let supporting = sessionItems.filter((s) => s.supporting);
  const seen = new Set(sessionItems.map((s) => v9NormSymKey(s.id)));
  const forexItems = SYMBOLS_DATA.find((c) => c.cat === "FOREX")?.items || [];

  if (v9SymPreviewEnabled(sessionPairs)) {
    if (trading.length < 5) {
      const pad = forexItems
        .filter((it) => !seen.has(v9NormSymKey(it.id)))
        .slice(0, Math.max(0, 5 - trading.length))
        .map((it) => {
          seen.add(v9NormSymKey(it.id));
          return {
            ...v9BuildSessionSymbolEntry(it.id, null, "Forex", V9_KNOWN_SYMBOL_CATALOG, false),
            name: it.name || it.id,
            previewPad: true,
          };
        });
      trading = [...trading, ...pad];
    }
    if (supporting.length === 0) {
      supporting = forexItems
        .filter((it) => !seen.has(v9NormSymKey(it.id)))
        .slice(0, 2)
        .map((it) => {
          seen.add(v9NormSymKey(it.id));
          return {
            ...v9BuildSessionSymbolEntry(it.id, null, "Forex", V9_KNOWN_SYMBOL_CATALOG, true),
            name: it.name || it.id,
            previewPad: true,
          };
        });
    }
  }

  // Keep the active chart symbol in its role group — pin it to the top of that group only.
  const activeKey = v9NormSymKey(fallbackSymbol);
  const pinActive = (list) => {
    if (!activeKey || !list?.length) return list || [];
    const hit = list.find((s) => v9NormSymKey(s.id) === activeKey);
    if (!hit) return list;
    return [hit, ...list.filter((s) => v9NormSymKey(s.id) !== activeKey)];
  };

  return [
    {
      role: "trading",
      label: "Trading",
      hint: "Trade symbols",
      items: pinActive(trading),
    },
    {
      role: "supporting",
      label: "Supporting",
      hint: "Context only",
      items: pinActive(supporting),
    },
  ];
}

function v9FilterSessionSymbolGroups(groups, searchQuery) {
  const q = String(searchQuery || "").toLowerCase();
  return groups
    .map((g) => {
      const filtered = (g.items || []).filter(
        (s) =>
          !q ||
          s.id.toLowerCase().startsWith(q) ||
          s.name.toLowerCase().split(/[\s/\-]+/).some((w) => w.startsWith(q))
      );
      if (!filtered.length && !(g.role && !q)) return null;
      // Keep empty Supporting/Trading sections visible when not searching.
      if (!filtered.length && g.role) return { ...g, items: [] };
      return { ...g, items: filtered };
    })
    .filter(Boolean);
}

function v9ResolveSessionFileId(sessionPairs, symbolId, fileIdFromEntry) {
  if (fileIdFromEntry != null) return fileIdFromEntry;
  if (!sessionPairs?.length) return null;
  const hit = sessionPairs.find((p) => v9NormSymKey(p.ticker) === v9NormSymKey(symbolId));
  return hit?.fileId ?? null;
}

/** Same normalization compare-overlay uses to match tickers to /api/files rows. */
function v9CompareTickerKey(s) {
  return String(s || "").replace(/[\s\-_/.]/g, "").toUpperCase();
}

function v9ActiveCompareOverlay() {
  if (typeof window === "undefined") return null;
  try {
    const ch = typeof window.getActiveChart === "function" ? window.getActiveChart() : window.chart;
    return ch?.compareOverlay || null;
  } catch (_) {
    return null;
  }
}

/** Kick /api/files load so Compare (+) can resolve fileIds for list rows. */
function v9EnsureCompareFilesLoaded() {
  const co = v9ActiveCompareOverlay();
  if (!co) return Promise.resolve(false);
  if (Array.isArray(co.availableFiles) && co.availableFiles.length > 0) return Promise.resolve(true);
  if (typeof co.loadAvailableSymbols === "function") {
    try {
      return Promise.resolve(co.loadAvailableSymbols()).then(() => true).catch(() => false);
    } catch (_) {
      return Promise.resolve(false);
    }
  }
  return Promise.resolve(false);
}

/**
 * Resolve a dataset id for Compare: session fileId first, then the full /api/files
 * catalog by ticker. Do not use getCompareSourceFiles() here — that list is
 * session-scoped and hides other pairs that still have datasets on disk.
 */
function v9ResolveCompareFileId(symbolId, fileIdHint, sessionPairs) {
  if (fileIdHint != null) {
    const n = parseInt(fileIdHint, 10);
    if (Number.isFinite(n)) return n;
  }
  if (sessionPairs?.length) {
    const fromSession = v9ResolveSessionFileId(sessionPairs, symbolId, null);
    if (fromSession != null) {
      const n = parseInt(fromSession, 10);
      if (Number.isFinite(n)) return n;
    }
  }
  const co = v9ActiveCompareOverlay();
  if (!co) return null;
  const files = Array.isArray(co.availableFiles) ? co.availableFiles : [];
  const key = v9CompareTickerKey(symbolId);
  if (!key || !files.length) return null;
  for (const file of files) {
    const raw = String(file?.original_name || file?.name || "").replace(/\.(csv|CSV)$/, "");
    const extracted = extractDatasetTicker(raw) || raw;
    const firstSeg = raw.split(/[_\s]/)[0] || raw;
    if (
      v9CompareTickerKey(extracted) === key ||
      v9CompareTickerKey(firstSeg) === key ||
      v9CompareTickerKey(raw) === key
    ) {
      const id = parseInt(file.id, 10);
      if (Number.isFinite(id)) return id;
    }
  }
  return null;
}

function v9FindCompareOverlayByFileId(fileId) {
  if (fileId == null) return null;
  const overlays = v9ActiveCompareOverlay()?.overlays;
  if (!Array.isArray(overlays) || overlays.length === 0) return null;
  const key = String(fileId);
  return overlays.find((o) => String(o?.fileId) === key) || null;
}

function v9FindCompareOverlayBySymbol(symbolId) {
  if (!symbolId) return null;
  const overlays = v9ActiveCompareOverlay()?.overlays;
  if (!Array.isArray(overlays) || overlays.length === 0) return null;
  const key = v9NormSymKey(symbolId);
  return overlays.find((o) => v9NormSymKey(o?.symbol || o?.symbolName || o?.name) === key) || null;
}

function v9IsComparedFileId(fileId) {
  return !!v9FindCompareOverlayByFileId(fileId);
}

/** Chrome-side compare membership — lets Symbols list show × even when a dataset is missing. */
const v9CompareChromeKeys = new Set();

function v9MarkCompareChrome(symbolId, on) {
  const key = v9NormSymKey(symbolId);
  if (!key) return false;
  if (on) v9CompareChromeKeys.add(key);
  else v9CompareChromeKeys.delete(key);
  try {
    window.dispatchEvent(new CustomEvent("v9-compare-chrome-changed", { detail: { symbol: key, on: !!on } }));
  } catch (_) { /* ignore */ }
  return true;
}

function v9IsComparedSymbol(symbolId, fileId) {
  if (v9CompareChromeKeys.has(v9NormSymKey(symbolId))) return true;
  if (fileId != null && v9IsComparedFileId(fileId)) return true;
  return !!v9FindCompareOverlayBySymbol(symbolId);
}

/** Active chart ticker (toolbar / chart.currentSymbol) — never a compare overlay. */
function v9ActiveChartSymbolKey(hint) {
  if (hint && v9NormSymKey(hint)) return v9NormSymKey(hint);
  if (typeof window === "undefined") return "";
  try {
    const ch =
      typeof window.getActiveChart === "function" ? window.getActiveChart() : window.chart;
    const raw = ch?.currentSymbol ?? ch?.symbol ?? "";
    const display = displayChartSessionSymbol(raw) || raw;
    return v9NormSymKey(display);
  } catch (_) {
    return "";
  }
}

function v9IsActiveChartSymbol(symbolId, activeHint) {
  const key = v9NormSymKey(symbolId);
  if (!key) return false;
  const active = v9ActiveChartSymbolKey(activeHint);
  return !!active && key === active;
}

/**
 * Chart symbol cannot stay in compare. Drop chrome membership + overlay when a
 * symbol becomes (or already is) the primary series.
 */
function v9PurgeCompareForChartSymbol(symbolId, fileId) {
  if (!symbolId) return Promise.resolve(false);
  const key = v9NormSymKey(symbolId);
  const wasChrome = key && v9CompareChromeKeys.has(key);
  const wasOverlay =
    (fileId != null && v9IsComparedFileId(fileId)) || !!v9FindCompareOverlayBySymbol(symbolId);
  if (!wasChrome && !wasOverlay) {
    v9MarkCompareChrome(symbolId, false);
    return Promise.resolve(false);
  }
  return Promise.resolve(v9RemoveCompareSymbol(fileId, symbolId)).then(() => true);
}

const V9_MAX_COMPARE_OVERLAYS = 4;

function v9CompareOverlayCount() {
  const overlays = v9ActiveCompareOverlay()?.overlays;
  return Array.isArray(overlays) ? overlays.length : 0;
}

/** Chart overlays + chrome-only memberships (unique symbols). */
function v9CompareMembershipCount() {
  const keys = new Set();
  v9CompareChromeKeys.forEach((k) => keys.add(k));
  const overlays = v9ActiveCompareOverlay()?.overlays;
  if (Array.isArray(overlays)) {
    overlays.forEach((o) => {
      const k = v9NormSymKey(o?.symbol || o?.symbolName || o?.name);
      if (k) keys.add(k);
    });
  }
  return keys.size;
}

function v9CanAddCompareOverlay() {
  return v9CompareMembershipCount() < V9_MAX_COMPARE_OVERLAYS;
}

/** Add a symbol as a compare overlay on the active chart (no picker window). */
function v9AddCompareSymbol(symbolId, fileId, sessionPairs, activeSymbolHint) {
  if (typeof window === "undefined") return Promise.resolve(false);
  const sym = String(symbolId || "").trim();
  const notify = (msg) => {
    const ac = typeof window.getActiveChart === "function" ? window.getActiveChart() : window.chart;
    ac?.showNotification?.(msg);
  };

  // Primary chart series can never join compare — it already owns the chart.
  if (v9IsActiveChartSymbol(sym, activeSymbolHint)) {
    return v9PurgeCompareForChartSymbol(sym, fileId).then(() => false);
  }

  v9EnsureCompareFilesLoaded();
  const fid = v9ResolveCompareFileId(sym, fileId, sessionPairs);
  if (v9IsComparedSymbol(sym, fid)) {
    v9MarkCompareChrome(sym, true);
    return Promise.resolve(true);
  }
  if (!v9CanAddCompareOverlay()) {
    notify(`Maximum ${V9_MAX_COMPARE_OVERLAYS} compare symbols`);
    return Promise.resolve(false);
  }

  // Always flip the Symbols list to × so compare UI is usable even without a dataset.
  v9MarkCompareChrome(sym, true);

  if (!Number.isFinite(fid)) {
    // Chrome-only membership — no toast. Chart will plot when a dataset exists.
    return Promise.resolve(true);
  }

  // Multichart: route through the command bus so the overlay lands on the focused panel.
  const grid = window.__multichartGrid;
  if (grid && typeof grid.runCommand === "function") {
    const panelId = typeof grid.getFocusedPanelId === "function" ? grid.getFocusedPanelId() : null;
    const opts = panelId ? { panelId } : undefined;
    return grid.runCommand("addCompareSymbol", { fileId: fid, symbol: sym, mode: "same-scale" }, opts)
      .then(() => true)
      .catch((err) => {
        console.warn("[V9 compare] addCompareSymbol on panel failed", err);
        // Keep chrome membership so the list still shows × for exit.
        return true;
      });
  }

  const ch =
    typeof window.getActiveChart === "function"
      ? window.getActiveChart()
      : window.chart;
  if (ch?.compareOverlay && typeof ch.compareOverlay.addSymbolWithMode === "function") {
    return Promise.resolve(ch.compareOverlay.addSymbolWithMode(fid, sym, "same-scale"))
      .then(() => true)
      .catch(() => true);
  }
  return Promise.resolve(true);
}

/** Remove a compare overlay by session fileId and/or symbol (toggle counterpart to add). */
function v9RemoveCompareSymbol(fileId, symbolId) {
  if (typeof window === "undefined") return Promise.resolve(false);
  v9MarkCompareChrome(symbolId, false);
  const fid = fileId != null ? parseInt(fileId, 10) : NaN;
  const hitByFile = Number.isFinite(fid) ? v9FindCompareOverlayByFileId(fid) : null;
  const hit = hitByFile || v9FindCompareOverlayBySymbol(symbolId);
  if (!hit || hit.id == null) return Promise.resolve(true);

  const grid = window.__multichartGrid;
  if (grid && typeof grid.runCommand === "function" && Number.isFinite(fid)) {
    const panelId = typeof grid.getFocusedPanelId === "function" ? grid.getFocusedPanelId() : null;
    const opts = panelId ? { panelId } : undefined;
    return grid.runCommand("removeCompareSymbol", { fileId: fid }, opts)
      .then(() => true)
      .catch((err) => {
        console.warn("[V9 compare] removeCompareSymbol on panel failed", err);
        const co = v9ActiveCompareOverlay();
        if (co && typeof co.removeOverlay === "function") {
          co.removeOverlay(hit.id);
          return true;
        }
        return true;
      });
  }

  const co = v9ActiveCompareOverlay();
  if (co && typeof co.removeOverlay === "function") {
    co.removeOverlay(hit.id);
    return Promise.resolve(true);
  }
  return Promise.resolve(true);
}

/** Snap a positive price string to the instrument tick for Place Order display. */
function v9SnapPositivePriceStr(raw, om) {
  const pos = v9PositivePriceStr(raw);
  if (!pos) return "";
  const n = parseFloat(pos);
  if (!(n > 0)) return "";
  return v9FormatSnappedOrderPrice(n, om || (typeof window !== "undefined" ? window.chart?.orderManager : null));
}

/** Keep React ENTRY row price aligned with hidden #orderEntryPrice (single entry only). */
function v9ApplyLiveEntryPriceToRows(setEntryRows, entryPriceStr) {
  if (!entryPriceStr) return;
  const om = typeof window !== "undefined" ? window.chart?.orderManager : null;
  const snapped = v9SnapPositivePriceStr(entryPriceStr, om) || String(entryPriceStr);
  setEntryRows((rows) => {
    if (!rows.length || rows.length > 1) return rows;
    const cur = parseFloat(rows[0].price || "0");
    const next = parseFloat(snapped);
    if (!Number.isFinite(next) || next <= 0) return rows;
    if (Math.abs(cur - next) < 1e-8) return rows;
    return [{ ...rows[0], price: snapped }];
  });
}

/** Market orders: entry preview must track live close — not a stale React row price. */
function v9ShouldAnchorEntryToLiveMarket(om) {
  if (!om) return true;
  if (om._previewEntryDecoupledFromRR) return false;
  const activeOt =
    document.querySelector("#orderPanel .order-type-btn.active")?.dataset?.type ||
    om.orderType ||
    "market";
  // Market tab: entry always follows live price; RR tool only drives TP/SL.
  if (activeOt === "market") return true;
  const src = om._previewEntrySource;
  if (src === "riskReward" || src === "manual") return false;
  if (src === "market") return true;
  return !om._previewEntryLinkedToRiskReward;
}

/** RR tool selected but Execute not clicked — order rail must stay independent of tool ladder. */
function v9IsRrSelectedWithoutExecute(om) {
  return !!(
    om &&
    !om._rrExecuteArmed &&
    typeof om._getSelectedRiskRewardDrawing === "function" &&
    om._getSelectedRiskRewardDrawing()
  );
}

/** Market orders: entry preview must track live close — not a stale React row price. */
function v9RefreshMarketOrderEntryFromChart(om, setEntryRows) {
  if (!om || om.isDraggingPreviewLine) return;
  if (om._orderPlacedAwaitingReset) return;
  if (!v9ShouldAnchorEntryToLiveMarket(om)) return;
  const activeOt =
    document.querySelector("#orderPanel .order-type-btn.active")?.dataset?.type ||
    om.orderType ||
    "market";
  if (activeOt !== "market") return;
  try {
    om.updateOrderPanelPrice?.();
  } catch (_) {}
  const ep = document.getElementById("orderEntryPrice")?.value ?? "";
  if (ep) v9ApplyLiveEntryPriceToRows(setEntryRows, ep);
  // When an iframe tile is focused, the parent must not draw preview SVG on
  // getActiveChart() — panel-B draft is owned by setDraftPreview → iframe OM.
  try {
    const iframeFocused = typeof om._shouldSkipParentOrderRailLivePriceForFocusedIframeTile === "function"
      && om._shouldSkipParentOrderRailLivePriceForFocusedIframeTile();
    if (!iframeFocused) om.updatePreviewLines?.();
  } catch (_) {}
}

/** Lightweight live market entry tick — updates hidden + React rows; preview only when price moves. */
function v9TickMarketOrderEntryFromChart(om, setEntryRows) {
  if (!om || om.isDraggingPreviewLine || om._orderPlacedAwaitingReset) return;
  if (!v9ShouldAnchorEntryToLiveMarket(om)) return;
  const activeOt =
    document.querySelector("#orderPanel .order-type-btn.active")?.dataset?.type ||
    om.orderType ||
    "market";
  if (activeOt !== "market") return;
  const prev = parseFloat(document.getElementById("orderEntryPrice")?.value || "0");
  try {
    om.updateOrderPanelPrice?.();
  } catch (_) {}
  const ep = document.getElementById("orderEntryPrice")?.value ?? "";
  if (ep) v9ApplyLiveEntryPriceToRows(setEntryRows, ep);
  const next = parseFloat(ep);
  if (Number.isFinite(next) && Number.isFinite(prev) && Math.abs(next - prev) >= 1e-10) {
    try {
      const iframeFocused = typeof om._shouldSkipParentOrderRailLivePriceForFocusedIframeTile === "function"
        && om._shouldSkipParentOrderRailLivePriceForFocusedIframeTile();
      if (!iframeFocused) om.updatePreviewLines?.();
    } catch (_) {}
  }
}

const CHART_TARGET_DRAG_LEAD_MS = 600;

/** Chart SL/TP drag just finished — React row may still be stale vs #tpPrice/#slPrice. */
function v9IsChartTargetDragLead(om) {
  return !!(
    om?._lastChartTargetDragAt &&
    Date.now() - om._lastChartTargetDragAt < CHART_TARGET_DRAG_LEAD_MS
  );
}

/** Hidden OM input has a chart-dragged price — do not overwrite with stale React row. */
function v9OmManualHiddenPriceWins(om, hiddenId, reactRowPx) {
  if (!om) return false;
  if (v9IsChartTargetDragLead(om)) return true;
  const manual =
    hiddenId === "tpPrice"
      ? om.tpManuallyPositioned
      : hiddenId === "slPrice"
        ? om.slManuallyPositioned
        : false;
  if (!manual) return false;
  const dom = String(document.getElementById(hiddenId)?.value ?? "");
  const domN = parseFloat(dom);
  const reactN = parseFloat(reactRowPx);
  if (!Number.isFinite(domN) || domN <= 0) return false;
  return !Number.isFinite(reactN) || reactN <= 0 || Math.abs(domN - reactN) >= 1e-8;
}

/** Mid-edit price strings (".", "26.") — do not mirror/overwrite from hidden OM inputs.
 *  Empty "" is NOT partial for SL/TP recovery (see v9ShouldHoldReactPriceAgainstOmMirror).
 *  SIZE / risk fields still treat blank as mid-edit via v9IsBlankOrPartialDecimalInput. */
function v9IsPartialDecimalInput(str) {
  const s = String(str ?? "").trim();
  if (s === ".") return true;
  if (s.endsWith(".")) return true;
  return false;
}

/** Blank or mid-edit — use for SIZE/risk so clearing the field does not push "" into OM. */
function v9IsBlankOrPartialDecimalInput(str) {
  if (String(str ?? "").trim() === "") return true;
  return v9IsPartialDecimalInput(str);
}

/** Skip OM→React price mirror while typing (partial decimals, or empty field that still has focus). */
function v9ShouldHoldReactPriceAgainstOmMirror(reactPrice, focused) {
  if (v9IsPartialDecimalInput(reactPrice)) return true;
  if (focused && String(reactPrice ?? "").trim() === "") return true;
  return false;
}

/** Valid positive price from hidden OM inputs — never treat blank/0 as a sync source that wipes React. */
function v9PositivePriceStr(raw) {
  const s = String(raw ?? "").trim();
  if (!s) return null;
  const n = parseFloat(s);
  return Number.isFinite(n) && n > 0 ? s : null;
}

/** SIZE rail input — allow free typing; cap fractional digits (default 3). */
function v9SanitizeSizeInputRaw(raw, sizeMode, symbolType, maxDecimals = 3) {
  let v = String(raw ?? "");
  if (sizeMode === "#" && symbolType === "futures") {
    if (!/^\d*$/.test(v)) return null;
    return v;
  }
  if (!/^-?\d*\.?\d*$/.test(v)) return null;
  if (v.length > 18) return null;
  const dot = v.indexOf(".");
  if (dot >= 0) {
    const frac = v.slice(dot + 1);
    if (frac.length > maxDecimals) {
      v = `${v.slice(0, dot + 1)}${frac.slice(0, maxDecimals)}`;
    }
  }
  if (sizeMode === "%") {
    const n = parseFloat(v);
    if (!isNaN(n) && n > 100) return null;
  }
  return v;
}

function v9FormatSizeInputOnBlur(raw, sizeMode, symbolType, accountEquity) {
  const s = String(raw ?? "").trim();
  if (s === "" || s === ".") return "0";
  const n = parseFloat(s);
  if (!Number.isFinite(n)) return "0";
  if (sizeMode === "#" && symbolType === "futures") {
    return String(Math.max(0, Math.floor(n)));
  }
  if (sizeMode === "%") {
    return String(Math.max(0, Math.min(100, parseFloat(n.toFixed(2)))));
  }
  if (sizeMode === "$") {
    const capped = Math.max(0, Math.min(accountEquity, n));
    return String(parseFloat(capped.toFixed(3)));
  }
  if (sizeMode === "#") {
    return String(parseFloat(Math.max(0, n).toFixed(3)));
  }
  return String(n);
}

/** SIZE rail stepper: $/amount by 1; lot (#) by 0.01 (0.001 at/below 0.01); futures by 1. */
function v9SizeStepperStep(sizeMode, symbolType, currentVal = null, dir = 1) {
  if (sizeMode === "%") return 0.5;
  if (sizeMode === "$") return 1;
  if (sizeMode === "#") {
    if (symbolType === "futures") return 1;
    const n = parseFloat(currentVal) || 0;
    if (dir > 0 && n === 0) return 0.01;
    if (dir < 0 && n <= 0.01) return 0.001;
    if (n < 0.01) return 0.001;
    return 0.01;
  }
  return 1;
}

function v9ApplySizeStepperDelta(rawVal, dir, sizeMode, symbolType, accountEquity = null) {
  const step = v9SizeStepperStep(sizeMode, symbolType, rawVal, dir);
  const next = Math.max(0, parseFloat(rawVal || "0") + dir * step);
  let capped = next;
  if (sizeMode === "%") capped = Math.min(100, next);
  else if (sizeMode === "$" && Number.isFinite(accountEquity)) capped = Math.min(accountEquity, next);

  if (sizeMode === "#" && symbolType === "futures") {
    return String(Math.max(0, Math.floor(capped)));
  }
  if (sizeMode === "#") {
    const dec = step >= 0.01 ? 2 : 3;
    return String(parseFloat(capped.toFixed(dec)));
  }
  if (sizeMode === "$") {
    return String(parseFloat(capped.toFixed(3)));
  }
  if (sizeMode === "%") {
    return String(parseFloat(capped.toFixed(2)));
  }
  return String(capped);
}

/** Snap Place Order entry/SL/TP to the instrument tick (NQ/ES → .00/.25/.50/.75). */
function v9SnapOrderPriceToTick(n, om) {
  let px = Number(n);
  if (!Number.isFinite(px)) return px;
  const chart = typeof window !== "undefined" ? window.chart : null;
  const orderOm = om || chart?.orderManager;
  if (orderOm && typeof orderOm._snapOrderPriceToTick === "function") {
    const snapped = orderOm._snapOrderPriceToTick(px);
    if (Number.isFinite(snapped)) return snapped;
  }
  if (chart && typeof chart.snapPriceToTick === "function") {
    const snapped = chart.snapPriceToTick(px);
    if (Number.isFinite(snapped)) return snapped;
  }
  return px;
}

function v9FormatSnappedOrderPrice(n, om) {
  const snapped = v9SnapOrderPriceToTick(n, om);
  if (!Number.isFinite(snapped)) return "0";
  if (om && typeof om.formatPrice === "function") return om.formatPrice(snapped);
  const chart = typeof window !== "undefined" ? window.chart : null;
  const orderOm = om || chart?.orderManager;
  if (orderOm && typeof orderOm.formatPrice === "function") return orderOm.formatPrice(snapped);
  return String(snapped);
}

function v9NormalizePriceInputOnBlur(raw, om) {
  const s = String(raw ?? "").trim();
  if (s === "" || s === ".") return "0";
  if (!/^\d*\.?\d*$/.test(s)) return "0";
  const n = parseFloat(s);
  if (!Number.isFinite(n)) return "0";
  if (!(n > 0)) return "0";
  return v9FormatSnappedOrderPrice(n, om || (typeof window !== "undefined" ? window.chart?.orderManager : null));
}

/** One price increment for entry/SL/TP steppers — chart tick grid, then OM pip, then display precision. */
function v9OrderPriceTickStep(om) {
  const chart = typeof window !== "undefined" ? window.chart : null;
  if (chart && typeof chart.getTickSize === "function") {
    const tick = chart.getTickSize();
    if (Number.isFinite(tick) && tick > 0) return tick;
  }
  if (om && Number.isFinite(om.pipSize) && om.pipSize > 0) return om.pipSize;
  const prec =
    om && typeof om.getPricePrecision === "function" ? om.getPricePrecision() : 5;
  return Math.pow(10, -prec);
}

function v9StepOrderPrice(currentStr, dir, om, entryAnchor) {
  const step = v9OrderPriceTickStep(om);
  const prec =
    om && typeof om.getPricePrecision === "function" ? om.getPricePrecision() : 5;
  let base = parseFloat(currentStr);
  if (!(Number.isFinite(base) && base > 0)) {
    const anchor =
      typeof entryAnchor === "number"
        ? entryAnchor
        : parseFloat(entryAnchor ?? "");
    if (Number.isFinite(anchor) && anchor > 0) {
      base = anchor;
    } else {
      base = 0;
    }
  }
  base = v9SnapOrderPriceToTick(base, om);
  let next = base + dir * step;
  if (!(next > 0)) next = 0;
  else next = v9SnapOrderPriceToTick(next, om);
  if (om && typeof om.formatPrice === "function") {
    return om.formatPrice(next, prec);
  }
  return Number.isFinite(next) ? next.toFixed(prec) : "0";
}

/** Entry / market price used when SL or TP steppers start from 0. */
function v9ResolveEntryAnchorPrice(om, entryRowPrice) {
  const fromRow = parseFloat(entryRowPrice ?? "");
  if (Number.isFinite(fromRow) && fromRow > 0) return fromRow;
  const ep = parseFloat(
    (typeof document !== "undefined" ? document.getElementById("orderEntryPrice")?.value : "") || "0"
  );
  if (Number.isFinite(ep) && ep > 0) return ep;
  const live = v9GetCurrentMarketPrice(om);
  return live > 0 ? live : 0;
}

function v9GetCurrentMarketPrice(om) {
  try {
    const candle = om?.getCurrentCandle?.();
    const px = candle?.c ?? candle?.close;
    const n = Number(px);
    return Number.isFinite(n) && n > 0 ? n : 0;
  } catch (_) {
    return 0;
  }
}

/** Entry anchor for mirroring SL/TP when toggling BUY ↔ SELL. */
function v9ResolveDraftEntryPriceForMirror(om, entryRows) {
  const fromRow = parseFloat(entryRows?.[0]?.price ?? "0");
  if (Number.isFinite(fromRow) && fromRow > 0) return fromRow;
  if (typeof document !== "undefined") {
    const h = parseFloat(document.getElementById("orderEntryPrice")?.value ?? "0");
    if (Number.isFinite(h) && h > 0) return h;
  }
  return v9GetCurrentMarketPrice(om);
}

/** Reflect a price level across entry (same pip distance, opposite side). */
function v9MirrorPriceAcrossEntry(price, entryPx, om) {
  const p = parseFloat(price);
  let e = parseFloat(entryPx);
  if (!Number.isFinite(p) || p <= 0) return price;
  if (!Number.isFinite(e) || e <= 0) {
    e = v9GetCurrentMarketPrice(om);
    if (!Number.isFinite(e) || e <= 0) return price;
  }
  const prec = typeof om?.getPricePrecision === "function" ? om.getPricePrecision(e) : 5;
  const mirrored = parseFloat((2 * e - p).toFixed(prec));
  const fmt = typeof om?.formatPrice === "function" ? om.formatPrice(mirrored) : null;
  return fmt != null ? String(fmt) : String(mirrored);
}

function v9FlipSlTpRowsForSideChange(om, entryRows, slRows, tpRows) {
  const entryPx = v9ResolveDraftEntryPriceForMirror(om, entryRows);
  const mirror = (px) => v9MirrorPriceAcrossEntry(px, entryPx, om);
  const nextSl = slRows.map((r) => ({ ...r, price: mirror(r.price) }));
  const nextTp = tpRows.map((r) => ({ ...r, price: mirror(r.price) }));
  return { nextSl, nextTp };
}

/** Market only within 1 tick of the live price line; otherwise Limit/Stop by side. */
function v9InferOrderTypeFromEntry(entryPrice, currentPrice, orderSide, om) {
  if (!Number.isFinite(entryPrice) || entryPrice <= 0) return "market";
  if (!Number.isFinite(currentPrice) || currentPrice <= 0) return "market";
  const tick = v9OrderPriceTickStep(om);
  const atMarket =
    Math.abs(entryPrice - currentPrice) <= Math.max(tick, Math.abs(currentPrice) * 1e-10);
  if (atMarket) return "market";
  const side = String(orderSide || "buy").toLowerCase();
  if (side === "buy") return entryPrice > currentPrice ? "stop" : "limit";
  return entryPrice < currentPrice ? "stop" : "limit";
}

function v9ApplyOrderTypeToOm(inferred, om) {
  if (!om || !["market", "limit", "stop"].includes(inferred)) return;
  if (om.orderType !== inferred) om.orderType = inferred;
  if (typeof document !== "undefined") {
    document.querySelectorAll("#orderPanel .order-type-btn").forEach((btn) => {
      btn.classList.toggle("active", btn.dataset.type === inferred);
    });
  }
  try {
    om.updatePlaceButtonText?.();
  } catch (_) {}
}

/** Session Advanced-order gate (split entry / multi-TP / BE / trailing). */
function v9SessionAdvancedOrderAllowed() {
  try {
    const om = typeof window !== "undefined" ? window.chart?.orderManager : null;
    if (om && typeof om._isAdvancedOrderAllowed === "function") {
      return !!om._isAdvancedOrderAllowed();
    }
    if (om && om.advancedOrderEnabled === false) return false;
    const tgl = typeof document !== "undefined" ? document.getElementById("advancedOrderToggle") : null;
    if (tgl && !tgl.checked) return false;
    const sess =
      (typeof window !== "undefined" && (window.backtestingSession || window.chart?.backtestingSession)) || null;
    if (sess && Object.prototype.hasOwnProperty.call(sess, "advanced_order") && !sess.advanced_order) {
      return false;
    }
    if (tgl) return !!tgl.checked;
    return !!sess?.advanced_order;
  } catch (_e) {
    return false;
  }
}

/** Mirror V9 SL advanced rail (BE / Trailing) into hidden #orderPanel fields placeOrder reads. */
function v9SyncSlAdvToHiddenOrderPanel({
  slAdvMode = "none",
  panelMode = "advanced",
  slBeUnit = "rr",
  slBeTrigger = "1.5",
  slBeOffset = "0",
  slTslUnit = "rr",
  slTslActivation = "1",
  slTslTrail = "0.5",
  slTslStep = "0.25",
} = {}) {
  if (typeof document === "undefined") return;
  const om = window.chart?.orderManager;
  const advOk = v9SessionAdvancedOrderAllowed();
  const mode = (!advOk || panelMode !== "advanced") ? "none" : (slAdvMode || "none");
  const unitToOm = (u) => (u === "dollar" ? "amount" : u === "pips" ? "pips" : "rr");

  const setIn = (id, val) => {
    const el = document.getElementById(id);
    if (!el) return;
    const s = String(val ?? "");
    if (el.value === s) return;
    el.value = s;
    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
  };

  const beTgl = document.getElementById("autoBreakevenToggle");
  const trTgl = document.getElementById("trailingSLToggle");
  const beSettings = document.getElementById("breakevenSettings");
  const trSettings = document.getElementById("trailingSLSettings");
  const wantBe = mode === "breakeven";
  const wantTr = mode === "trailing";

  if (om) om._beTrailMutex = true;
  if (beTgl && beTgl.checked !== wantBe) beTgl.checked = wantBe;
  if (trTgl && trTgl.checked !== wantTr) trTgl.checked = wantTr;
  if (om) om._beTrailMutex = false;

  if (wantBe) {
    const omBeMode = unitToOm(slBeUnit);
    if (om) om.breakevenMode = omBeMode;
    document.querySelectorAll(".breakeven-mode-tab").forEach((t) => {
      t.classList.toggle("active", t.getAttribute("data-mode") === omBeMode);
    });
    const unitText = omBeMode === "rr" ? "R" : omBeMode === "pips" ? "Pips" : "$";
    document.querySelectorAll("[data-be-unit-label]").forEach((el) => { el.textContent = unitText; });
    document.querySelectorAll(".be-offset-input, .be-offset-label").forEach((el) => {
      el.style.display = omBeMode === "amount" ? "none" : "";
    });
    const trig = slBeTrigger || "0";
    if (omBeMode === "amount") setIn("breakevenAmount", trig);
    setIn("breakevenPips", trig);
    setIn("breakevenPipOffset", slBeOffset ?? "0");
    if (beSettings) beSettings.classList.remove("is-hidden");
    if (trSettings) trSettings.classList.add("is-hidden");
    try { om?.stopTrailingSL?.(); } catch (_) {}
    try { om?._updateBreakevenSummary?.(); } catch (_) {}
  } else if (wantTr) {
    const trMode = unitToOm(slTslUnit);
    try {
      if (om && typeof om._setTrailingUnitMode === "function") {
        if (om.trailingUnitMode !== trMode) om._setTrailingUnitMode(trMode);
      } else if (om) {
        om.trailingUnitMode = trMode;
      }
    } catch (_) {}
    setIn("trailingActivateRR", slTslActivation ?? "1");
    setIn("trailingStepSize", slTslTrail ?? "0.5");
    setIn("trailingActivatePips", slTslStep ?? "0.25");
    if (beSettings) beSettings.classList.add("is-hidden");
    if (trSettings) trSettings.classList.remove("is-hidden");
    try { om?.initializeTrailingSL?.(); } catch (_) {}
    try { om?._updateTrailingSummary?.(); } catch (_) {}
  } else {
    if (beSettings) beSettings.classList.add("is-hidden");
    if (trSettings) trSettings.classList.add("is-hidden");
    try { om?.stopTrailingSL?.(); } catch (_) {}
  }
}

function v9SyncOrderTypeFromEntryPrice(om, orderSide) {
  const entryPx = parseFloat(
    (typeof document !== "undefined" ? document.getElementById("orderEntryPrice")?.value : "") || "0"
  );
  if (!Number.isFinite(entryPx) || entryPx <= 0) return "market";
  const inferred = v9InferOrderTypeFromEntry(entryPx, v9GetCurrentMarketPrice(om), orderSide, om);
  v9ApplyOrderTypeToOm(inferred, om);
  try {
    om?.updatePreviewLines?.();
  } catch (_) {}
  return inferred;
}

/** Write entry into hidden OM input and flip Market/Limit/Stop tab when price leaves market. */
function v9PushEntryPriceAndDetectOrderType(priceStr, orderSide, om) {
  const s = String(priceStr ?? "");
  const entryPx = parseFloat(s);
  if (!Number.isFinite(entryPx) || entryPx <= 0) return "market";
  const el = typeof document !== "undefined" ? document.getElementById("orderEntryPrice") : null;
  if (el && el.value !== s) {
    el.value = s;
    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
  }
  return v9SyncOrderTypeFromEntryPrice(om, orderSide);
}

