        // overwrites a secondary panel (e.g. 15m) with the main's TF (e.g. 1h).
        if (!pci) {
          if (attempts++ < 60) setTimeout(apply, 200);
          return;
        }
        const rawTf = pci.currentTimeframe || sel?.timeframe;
        if (!rawTf) {
          if (attempts++ < 60) setTimeout(apply, 200);
          return;
        }
