          const useFuturesContractTp =
            sizeMode === "#" && currentSymbol.type === "futures" && oqTpFloor > 0;
          const useForexLotTp =
            sizeMode === "#" && currentSymbol.type !== "futures" && oqTpLots > 0 && tpActive.length > 1;
          const tpDistMode = v9SizeModeToTpDistribution(sizeMode);
