    setIndOpen(false);
    setIndSearch("");
    setIndSelectedId(null);
    setSDrop(null);
    setColorPicker(null);
    cpAlertAnchorRef.current = null;
    setScreenshotOpen(false);
    setLayersOpen(false);
    setSettDrop(null);
