                                <line x1={0} y1={Math.max(8,+tlStyle.midLineWidth+4)/2} x2={22} y2={Math.max(8,+tlStyle.midLineWidth+4)/2}
                                  stroke={open?"var(--accent)":"var(--text-muted)"} strokeWidth={+tlStyle.midLineWidth} strokeLinecap="round"/>
