                    const parChUpper = isParCh ? parChOrdered.find((e) => v9ParallelChannelRowIsUpper(e.row)) : null;
                    const parChAfterMid = isParCh ? parChOrdered.filter((e) => e !== parChUpper) : [];
                    const lines = isParCh
