                              background:isAct?`linear-gradient(90deg,transparent,${c.acL},transparent)`:isH?`linear-gradient(90deg,transparent,`+c.hvLn+`,transparent)`:"transparent",
                              boxShadow:isAct?`0 0 6px ${c.acG}`:"none",pointerEvents:"none",
